UPDATE ai_clipping
SET approve_yn = #{approveYn},
    mod_date = CURRENT_TIMESTAMP
WHERE seq = #{seq}

mapper.select:
/* com.mtf.kibs.mapper.AiClippingMapper.selectTodayPendingClippings */ SELECT seq, title, content, display_yn AS displayYn, approve_yn AS approveYn, del_yn AS delYn, DATE_FORMAT(reg_date, '%Y-%m-%d %H:%i:%s') AS regDate FROM ai_clipping WHERE del_yn = 'N' AND display_yn = 'N' AND DATE(reg_date) = CURDATE()
AND approve_yn = 'Y'
ORDER BY reg_date DESC
